insert into public.activities (id, world_id, topic_id, age_band, level, activity_type, title, learning_objective, content, xp_reward, coin_reward_minor_units, order_index) values
  ( 'explorer-money_basics-l1', 'coin-cove', 'money_basics', 'explorer', 1, 'lesson', 'What Is Money?', 'Recognise that money is used to get things people want or need.', $jsonb${"shortIntroduction":"Coins jingle. Notes rustle. But what IS money, really? Let's find out together.","story":"You walk into a little shop with your grown-up. You want an apple. The shop keeper doesn't want a hug or a high-five for it — she wants two coins. You give her two coins. She gives you the apple. That's money doing its job!","keyConcept":"Money is something we trade for the things we want or need, instead of swapping items directly.","vocabulary":[{"term":"money","definition":"Coins and notes we use to buy things"},{"term":"trade","definition":"Swapping one thing for another"},{"term":"value","definition":"How much something is worth"}],"explanation":"A long, long time ago, people used to swap things directly — a chicken for some bread, maybe. That got tricky fast! Money made it much simpler: everyone agrees that coins and notes are worth something, so you can use them to get almost anything.","interactiveActivity":"Sort a set of pictures into a 'Money' pile and a 'Not Money' pile.","gameIdea":"Coin Catch: tap real coin pictures as they float by, and dodge the leaf and rock decoys.","challenge":"Look around your home with a grown-up and find three things that cost money.","quiz":{"question":"Which of these is money?","options":["A coin","A leaf","A sticker","A rock"],"correct_answer":"A coin","explanation":"A coin is made specially so everyone agrees it can be used to buy things. A leaf, a sticker, and a rock are not — a shop keeper wouldn't take those for an apple!"},"feedbackMessage":{"success":"You spotted it! Coins are for buying things. ⭐","retry":"Close one! Think about what the shop keeper in the story actually wanted."},"rewardMessage":"You earned your very first Money Quest coins for learning what money is for!","parentNote":"This lesson introduces the most basic idea in financial literacy: that money is exchanged for goods and services, rather than assuming a child already grasps this. At 6-8, children are often still working out that a shop keeper wants specific coins, not just 'a nice gesture' — reinforcing this with real coins during a shopping trip is one of the most effective things you can do this week.","commonMisconception":"Children this age often think any small, round, or shiny object counts as money."}$jsonb$::jsonb, 15, 500, 1   ),
  ( 'builder-money_basics-l1', 'coin-cove', 'money_basics', 'builder', 1, 'lesson', 'Where Does Money Come From?', 'Explain that money is earned through work and can take different forms (cash, cards, digital).', $jsonb${"shortIntroduction":"Money doesn't just appear — someone earns it, and it can look different depending on where you use it.","story":"Amir's older cousin just got paid for babysitting. Amir notices something odd: no coins changed hands. The money went straight into an app on his cousin's phone. Amir asks, 'So... is that even real money?' His cousin laughs and says, 'It's exactly as real as coins — it's just a different form of the same thing.'","keyConcept":"Money is earned in exchange for work, and today it can exist as physical cash or as a digital balance — both represent the same kind of value.","vocabulary":[{"term":"earn","definition":"To get money by doing work"},{"term":"digital money","definition":"Money that exists as numbers in an account, not physical coins or notes"},{"term":"balance","definition":"How much money you currently have"}],"explanation":"People earn money by working — a job, a chore, selling something they made. That money can be handed over as physical coins and notes, or it can move between digital accounts without anyone touching a single coin. Both are real money; they're just different forms of the same idea.","interactiveActivity":"Match different ways people earn money (a job, selling something, a chore) to short scenario cards.","gameIdea":"Earn Your Coins: complete simple in-game 'jobs' to build up a fictional coin balance.","challenge":"Ask a grown-up to show you one example of digital money being used — a card tap, an app, or a bank transfer.","quiz":{"question":"Which of these is a way someone might earn money?","options":["Doing a job","Wishing really hard","Waiting for a rainy day","Asking a stranger"],"correct_answer":"Doing a job","explanation":"Money is earned by doing work of some kind — a job, a task, or selling something. Wishing, waiting, and asking strangers aren't reliable ways to earn money."},"feedbackMessage":{"success":"Exactly right — work is how money gets earned. 🎯","retry":"Think about what actually gives someone a reason to pay you."},"rewardMessage":"Coins earned for understanding where money actually comes from!","parentNote":"9-11 is a good age to start naming that money is earned, not given, and to demystify digital payments — cards and apps can feel like 'free money' to a child who's never watched cash physically change hands. If your family uses mostly digital payments, this is a good week to narrate a purchase out loud ('I'm paying with my card, which takes the money from my account, the same as if I'd handed over coins').","commonMisconception":"Children this age sometimes believe digital payments (card taps, app transfers) aren't 'real' money the way cash is, or that a card has its own unlimited supply."}$jsonb$::jsonb, 20, 750, 1   ),
  ( 'strategist-money_basics-l1', 'coin-cove', 'money_basics', 'strategist', 1, 'lesson', 'Money as a Tool, Not a Goal', 'Understand money as a shared system that only works because people agree to trust it, and recognise that different countries use different currencies for this system.', $jsonb${"shortIntroduction":"Money only 'works' because millions of strangers agree to trust the same idea. That's genuinely strange when you think about it.","story":"Priya is helping plan a school fundraiser and notices something: the coins in her pocket are worthless outside her own country. A friend visiting from abroad hands her a note from home, and neither of them can use it here. Priya realises money isn't some fixed, universal thing — it's a system that works because a specific group of people agree it does.","keyConcept":"Money is a shared system of trust, not a fixed universal object — different countries use different currencies, and a currency's value comes from people agreeing to use and trust it.","vocabulary":[{"term":"currency","definition":"The particular kind of money used in a country or region"},{"term":"trust","definition":"Believing something will work the way everyone expects it to"},{"term":"system","definition":"A set of things working together by agreed rules"}],"explanation":"A coin only has value because everyone around you agrees it does — there's nothing magic about the metal itself. This is why different countries can have completely different money (pounds, dollars, euros, yen, and many more), and why that money doesn't automatically work somewhere else. The 'value' isn't in the coin; it's in everyone's shared agreement to use it.","interactiveActivity":"Compare a few real currencies from different countries and notice what's different (name, symbol, and appearance) and what's the same (all used to buy things within their own country).","gameIdea":"Currency Explorer: match countries to their currencies and compare example prices.","challenge":"Find out what currency is used in a country you've never visited, and one interesting fact about it.","quiz":{"question":"Why doesn't money from one country automatically work in another?","options":["Because each country uses a different, separately-trusted currency","Because foreign money is fake","Because shops don't like tourists","Because coins wear out when they travel"],"correct_answer":"Because each country uses a different, separately-trusted currency","explanation":"Each country's money is its own system of shared trust — a shop in one country hasn't agreed to accept another country's currency, the same way you wouldn't trade game points from one app for a different app's currency."},"feedbackMessage":{"success":"You've got it — money is a system of trust, and that system is different in different places. 🌍","retry":"Think about what actually makes a coin 'work' when you hand it to a shop keeper."},"rewardMessage":"Coins awarded for a genuinely bigger-picture idea about what money actually is.","parentNote":"This lesson deliberately introduces the idea that money's value is a social agreement, not a fixed fact — a genuinely useful mental model heading into teenage years, when concepts like exchange rates, inflation, and 'why prices go up' start becoming relevant. It does not attempt to explain exchange rates or economics in depth; if your teen asks follow-up questions this lesson doesn't answer, that's a great sign, not a gap to worry about filling immediately.","commonMisconception":"Teenagers sometimes assume all money works the same way everywhere, or that currency value is a fixed, objective fact rather than something maintained by collective trust.","countryVariesNote":"Which currency is used, how it's valued, and how it can be exchanged for another country's currency are all things that genuinely differ by country — this lesson doesn't cover exchange rates in detail, since the rules and current rates vary and change over time."}$jsonb$::jsonb, 25, 1000, 1   ),
  ( 'explorer-needs_wants-l1', 'market-town', 'needs_wants', 'explorer', 1, 'lesson', 'Need It or Want It?', 'Sort everyday items into needs and wants.', $jsonb${"shortIntroduction":"Some things you must have. Some things you just really, really like. Let's tell them apart!","story":"You and your grown-up walk past a bakery. You spot bread for dinner — your tummy needs that! Then you spot a giant chocolate bar. You don't need it, but wow, you WANT it. Both feelings are real, but they're not the same thing.","keyConcept":"A need is something you must have to be okay. A want is something nice to have, even if you really like it.","vocabulary":[{"term":"need","definition":"Something you must have"},{"term":"want","definition":"Something nice to have, but not essential"}],"explanation":"Food, a warm coat, and a safe place to sleep are needs — you can't skip them. A new toy, a chocolate bar, or extra stickers are wants — lovely to have, but you'd still be okay without them, even if it doesn't feel that way in the moment.","interactiveActivity":"Drag pictures of items into a 'Need' bucket or a 'Want' bucket.","gameIdea":"Need or Want Sorter: a fast-tap sorting game with a happy sound for every correct answer.","challenge":"With a grown-up, sort ten things in your home into needs and wants.","quiz":{"question":"Which of these is a need?","options":["A winter coat","A video game","A toy car","Stickers"],"correct_answer":"A winter coat","explanation":"A winter coat keeps you warm and safe — that makes it a need. A video game, a toy car, and stickers are all fun, but you'd still be okay without them, which makes them wants."},"feedbackMessage":{"success":"Nicely sorted! You know the difference. 🌟","retry":"Not quite — think about what would happen if you didn't have it at all."},"rewardMessage":"Coins earned for telling needs and wants apart!","parentNote":"Needs-vs-wants is one of the earliest, most repeatable money conversations you can have — and it's genuinely hard for a 6-8 year old, since a strong want can feel exactly as urgent as a real need. A gentle, non-judgemental question ('what would happen if you didn't get it?') works far better than telling them they're wrong to want something. Wanting things is completely normal at this age; the goal is just building the habit of noticing the difference.","commonMisconception":"Children this age often believe that anything they want strongly enough must be a need."}$jsonb$::jsonb, 15, 500, 1   ),
  ( 'builder-needs_wants-l1', 'market-town', 'needs_wants', 'builder', 1, 'lesson', 'The Grey Area', 'Recognise that some items can be a need or a want depending on the situation.', $jsonb${"shortIntroduction":"Not everything sorts neatly into 'need' or 'want' — sometimes it genuinely depends.","story":"Leah's class is doing a project, and she needs a working calculator — hers just broke. Is a calculator a need or a want? It depends! For this project, right now, it's a need. But a brand new, fancier calculator when hers already works fine? That would be a want.","keyConcept":"Whether something is a need or a want can depend on the situation, not just the item itself.","vocabulary":[{"term":"situation","definition":"The specific circumstances at a particular time"},{"term":"essential","definition":"Absolutely necessary"}],"explanation":"A phone is a good example: for a teenager who uses it only for games and messaging friends, it's mostly a want. For someone who needs it to contact a parent or complete schoolwork, parts of that same phone start to look more like a need. The item doesn't change — the situation around it does.","interactiveActivity":"Look at five 'it depends' scenarios and decide what extra information would settle whether something is a need or a want.","gameIdea":"Smart Shopper: compare item options and reasons for buying them, not just prices.","challenge":"Think of one thing in your own life that's a need in some situations and a want in others — and explain why.","quiz":{"question":"A working laptop is required for online school homework. In that situation, what is it?","options":["A need","A want","Neither","Always a luxury"],"correct_answer":"A need","explanation":"When something is genuinely required to do something essential — like completing required schoolwork — it becomes a need in that specific situation, even though a laptop could be a want in a different context."},"feedbackMessage":{"success":"Exactly — you're thinking about the situation, not just the item. 🎯","retry":"Think about what the laptop is actually being used FOR in this situation."},"rewardMessage":"Coins earned for spotting a genuinely tricky 'it depends' case!","parentNote":"This lesson deliberately introduces nuance rather than a rigid rule — by 9-11, a purely black-and-white needs/wants framework starts to feel unconvincing to kids (rightly — real life is genuinely more complicated). A useful follow-up conversation is asking your child to argue BOTH sides for something they want, which builds real reasoning skill rather than rote categorising.","commonMisconception":"At this age, children sometimes swing the other way and start arguing that almost anything COULD be a need in the right situation, using nuance to avoid the distinction entirely rather than apply it thoughtfully."}$jsonb$::jsonb, 20, 750, 1   ),
  ( 'strategist-needs_wants-l1', 'market-town', 'needs_wants', 'strategist', 1, 'lesson', 'Needs, Wants, and Social Pressure', 'Analyse how social pressure and advertising can make a want feel like a need.', $jsonb${"shortIntroduction":"Advertisers are genuinely good at their jobs. Part of that job is making a want feel urgent, like a need.","story":"Jordan sees an ad: 'Everyone who's anyone has this.' Jordan doesn't actually need the product — their current one works fine. But something about the ad makes Jordan feel like they're missing out, almost left behind. That feeling is real. The 'need' behind it usually isn't.","keyConcept":"Advertising and social pressure are specifically designed to make wants feel urgent, like needs — recognising that design is a genuinely useful skill.","vocabulary":[{"term":"advertising","definition":"Content designed to persuade people to buy something"},{"term":"social pressure","definition":"Feeling like you should do or have something because others do"},{"term":"urgency","definition":"A feeling that something must happen right away"}],"explanation":"A lot of marketing isn't really about the product itself — it's about creating a feeling: fear of missing out, wanting to fit in, or worry that you're falling behind. None of those feelings mean the item is actually a need. Naming the feeling ('this ad is trying to make me feel urgency') is often enough to make a clearer decision.","interactiveActivity":"Look at a few real-style ad phrases and identify which persuasion technique each one is using (urgency, fitting in, fear of missing out).","gameIdea":"Money Choices: weigh a purchase decision against a scenario that includes social pressure.","challenge":"Next time you feel a strong urge to buy something after seeing an ad or a friend's post, pause and name what feeling is actually driving that urge.","quiz":{"question":"An ad says 'Don't be the only one without it!' What technique is this mainly using?","options":["Fear of missing out","A factual comparison","A safety warning","A price discount"],"correct_answer":"Fear of missing out","explanation":"This phrase is designed to trigger a fear of being left out or left behind — a real feeling, but not the same thing as a genuine need for the product."},"feedbackMessage":{"success":"You spotted the technique — that's a genuinely useful skill for life, not just money. 🎯","retry":"Look again at what emotion the phrase is trying to create in the reader."},"rewardMessage":"Coins earned for seeing past a persuasion technique to the actual want underneath.","parentNote":"This lesson is deliberately about recognising persuasion techniques, not about shaming your teen for wanting things that are influenced by ads or peers — that influence is normal and near-universal, including for adults. The goal is building a habit of noticing it, which tends to land much better as a shared, curious observation ('oh, that's the fear-of-missing-out one') than as a lecture about wasteful spending.","commonMisconception":"Teenagers sometimes believe they're personally immune to advertising's influence, which paradoxically makes the influence harder to notice when it's actually working on them."}$jsonb$::jsonb, 25, 1000, 1   ),
  ( 'explorer-saving-l1', 'golden-vault', 'saving', 'explorer', 1, 'lesson', 'What Does Saving Mean?', 'Understand that saving means keeping money instead of spending it right away.', $jsonb${"shortIntroduction":"What if, instead of spending your coins today, you kept them — and watched the pile grow?","story":"You get one coin every day for a small job you do at home. You could spend it right away on a small treat. Or you could put it in your jar and watch the pile grow bigger and bigger, day after day, until it's enough for something really special.","keyConcept":"Saving is putting money aside now so you can use it later, often for something bigger.","vocabulary":[{"term":"save","definition":"To keep money instead of spending it"},{"term":"later","definition":"Not right now, but in the future"}],"explanation":"If you save your coins instead of spending them all straight away, you'll have more later — enough for something bigger than you could get with just one day's coin.","interactiveActivity":"Watch a piggy bank fill up: add a coin each day and see the pile grow.","gameIdea":"Growing Piggy Bank: a simple tap-to-save game with a visible, growing coin pile.","challenge":"Save a fictional coin every day for five in-app days without spending it.","quiz":{"question":"What does 'saving' money mean?","options":["Spending it all today","Keeping it to use later","Losing it","Giving it away"],"correct_answer":"Keeping it to use later","explanation":"Saving means choosing to keep money instead of spending it right away, so you have more of it later — it doesn't disappear, it just waits for you."},"feedbackMessage":{"success":"You've got it — your coins are safe and growing! 🐷","retry":"Think about what happens to your coin jar if you keep adding to it and never take any out."},"rewardMessage":"Coins earned for understanding what saving really means!","parentNote":"Saving toward a visible goal is one of the most effective early money habits — a clear jar or a simple chart your child can actually see filling up tends to work far better at this age than a bank app or an abstract number. If your child spends what they save right away this week, that's a completely normal part of learning, not a setback to correct with a lecture.","commonMisconception":"Children this age sometimes think saved money 'disappears' or is wasted if it isn't spent immediately."}$jsonb$::jsonb, 15, 500, 1   ),
  ( 'builder-saving-l1', 'golden-vault', 'saving', 'builder', 1, 'lesson', 'Saving for Something Bigger', 'Set a simple savings goal and understand the trade-off between spending now and saving for later.', $jsonb${"shortIntroduction":"Every coin you save today is a coin you're choosing NOT to spend today. That trade-off is the whole idea.","story":"Maya wants a new sketchbook that costs more than her weekly allowance. She could ask for it as a gift, or she could save three weeks of allowance and buy it herself. She chooses to save. Some weeks it's tempting to spend on small treats instead — but she keeps her sketchbook goal in mind, and three weeks later, she buys it herself.","keyConcept":"Saving toward a specific goal means choosing not to spend on smaller things now, so you can afford something bigger later.","vocabulary":[{"term":"goal","definition":"Something specific you're saving up for"},{"term":"trade-off","definition":"Giving up one thing to get another"}],"explanation":"Every time you save instead of spend, you're making a trade-off: a small treat now, or steady progress toward something bigger later. Neither choice is wrong — but naming the trade-off clearly makes it easier to decide on purpose, rather than by accident.","interactiveActivity":"Set a simple savings goal with a target amount and track progress toward it.","gameIdea":"Reach Your Goal: allocate fictional coins toward a savings target across several rounds.","challenge":"Pick one real thing you'd like to save for, and figure out roughly how many weeks it would take at your current saving rate.","quiz":{"question":"Maya wants a sketchbook that costs more than one week's allowance. What's her best option if she wants to buy it herself?","options":["Save allowance over several weeks","Spend everything and hope","Give up on the idea","Ask a stranger for money"],"correct_answer":"Save allowance over several weeks","explanation":"Saving a little at a time, over several weeks, is how you reach a goal that costs more than you have in any single week — that's the whole point of a savings goal."},"feedbackMessage":{"success":"Right — small amounts really do add up over time. 📈","retry":"Think about what Maya could realistically do each week to get closer to her goal."},"rewardMessage":"Coins earned for setting a real goal and thinking through how to reach it!","parentNote":"This is a good age to let a child set and track their OWN savings goal, even a small one, and to let them experience the real trade-off of choosing not to spend on a smaller treat along the way. Resist the urge to top up the last bit of a goal for them — the experience of getting there on their own effort, even slowly, tends to matter more than the final amount.","commonMisconception":"Children this age often underestimate how quickly small, regular savings add up, and may give up on a goal that feels too far away in week one."}$jsonb$::jsonb, 20, 750, 1   ),
  ( 'strategist-saving-l1', 'golden-vault', 'saving', 'strategist', 1, 'lesson', 'Saving vs. Spending: The Real Trade-off', 'Evaluate saving decisions by weighing short-term enjoyment against longer-term goals, and understand that saved money can sometimes grow over time.', $jsonb${"shortIntroduction":"Some saved money can actually grow on its own over time. Here's the honest version of how — and why it's not magic.","story":"Theo has two options for money he doesn't need right now: spend it, or put it somewhere it might slowly grow over time by earning a small amount extra, sometimes called interest. He realises this only really matters if he leaves the money alone for a while — pulling it out quickly barely makes a difference.","keyConcept":"Money saved over a longer period can sometimes grow through interest, but the trade-off between enjoying money now and having more later is the real decision underneath every saving choice.","vocabulary":[{"term":"interest","definition":"A small extra amount some saved money can earn over time"},{"term":"long-term","definition":"Over a longer period, not just the next few weeks"},{"term":"opportunity cost","definition":"What you give up by choosing one option instead of another"}],"explanation":"Some ways of saving money can pay a small amount of interest — extra money added over time, usually because a bank or savings provider is using your saved money and paying you for the ability to do so. This only becomes meaningful over a genuinely long period; over a few weeks it's barely noticeable. The bigger decision is still the same one at any age: enjoy the money now, or have more of it later.","interactiveActivity":"Compare two saving scenarios over different lengths of time and notice how the effect of interest changes with time.","gameIdea":"Interest Grower: watch a small saved amount grow slowly over simulated months.","challenge":"Think of a real decision in your own life where 'enjoy it now' and 'wait for more later' are genuinely both reasonable choices — and decide which you'd pick, and why.","quiz":{"question":"Why does interest matter more over a longer period of time?","options":["Because the extra amount has more time to build up","Because banks prefer long-term customers","Because prices go down over time","Because interest is only legal after a year"],"correct_answer":"Because the extra amount has more time to build up","explanation":"Interest is typically calculated regularly on the amount saved, so the longer money stays saved, the more time it has to accumulate — a short period simply doesn't give it much time to add up."},"feedbackMessage":{"success":"Exactly — time is the real ingredient that makes interest meaningful. ⏳","retry":"Think about what actually changes between a savings plan that runs for a few weeks versus several years."},"rewardMessage":"Coins earned for understanding how saving and time actually work together.","parentNote":"This lesson introduces interest honestly but deliberately keeps the numbers illustrative rather than tied to any real product or provider, since actual interest rates and savings account terms vary significantly by country, provider, and over time. If your teen wants to understand a real savings account or product, that's a great conversation to have directly with them using your own family's actual bank or provider information, since this lesson can't responsibly give specific financial guidance.","commonMisconception":"Teenagers sometimes expect interest to make a dramatic difference over a short period, then feel savings 'don't really work' when the effect over a few weeks is barely noticeable.","countryVariesNote":"Interest rates, how they're calculated, and the rules around savings accounts vary significantly by country and by provider, and change over time — this lesson explains the general idea only, not any specific real-world rate."}$jsonb$::jsonb, 25, 1000, 1   ),
  ( 'explorer-currencies-l1', 'sky-exchange', 'currencies', 'explorer', 1, 'lesson', 'Money Looks Different Everywhere', 'Recognise that different countries use different money.', $jsonb${"shortIntroduction":"Did you know the coins in your pocket wouldn't work in every country? Let's explore why!","story":"A friend visits from far away and shows you a coin from their home. It's shiny, but it looks nothing like your coins — different colours, different pictures, different shapes! Your friend explains: 'This is what money looks like where I live.'","keyConcept":"Different countries have their own kind of money, and it looks different from place to place.","vocabulary":[{"term":"country","definition":"A place with its own government and rules"},{"term":"different","definition":"Not the same"}],"explanation":"Just like countries can have different flags, languages, and foods, they also have different money. The coins and notes you use every day are made specially for where you live.","interactiveActivity":"Look at pictures of coins and notes from a few different countries and spot what's different about each one.","gameIdea":"Currency Explorer: match pictures of money to the country it belongs to.","challenge":"Ask a grown-up if they have ever seen money from another country, and what it looked like.","quiz":{"question":"Do all countries use the exact same money?","options":["No, it's different in different places","Yes, it's always identical","Only rich countries have money","Money never changes"],"correct_answer":"No, it's different in different places","explanation":"Different countries have their own kind of money, which is why your friend's coin looked so different from yours — each country makes its own."},"feedbackMessage":{"success":"That's right — money looks different all around the world! 🌍","retry":"Think about your friend's coin in the story — did it look just like yours?"},"rewardMessage":"Coins earned for exploring money from around the world!","parentNote":"This lesson gently introduces that currencies differ by country, without needing exchange rates or economics — a concrete, visual comparison (showing your child a real foreign coin or note, or photos of a few, if you have any) is a lovely way to reinforce this at home.","commonMisconception":"Young children sometimes assume all money in the world works and looks the same, since it's all 'just money' from their perspective."}$jsonb$::jsonb, 15, 500, 1   ),
  ( 'builder-currencies-l1', 'sky-exchange', 'currencies', 'builder', 1, 'lesson', 'Cash, Cards, and Currencies', 'Understand that money can be physical or digital, and that different countries use different named currencies.', $jsonb${"shortIntroduction":"Coins and notes are just one way money can exist — and every country's currency has its own name.","story":"Sam is helping plan a family trip abroad. Sam's parent explains that the money at home won't work there — they'll need a different currency, with a different name and different-looking notes and coins, just for that country.","keyConcept":"Money can be physical (coins and notes) or digital (numbers in an account), and different countries each use their own named currency.","vocabulary":[{"term":"currency","definition":"The specific kind of money used in a country"},{"term":"physical money","definition":"Coins and notes you can hold"},{"term":"digital money","definition":"Money that exists as numbers in an account"}],"explanation":"Every country has a named currency — pounds, dollars, euros, yen, and many others. Whether that currency is used as physical coins and notes or moved around digitally through cards and apps, it's still that country's own currency.","interactiveActivity":"Match a few real currency names to the countries that use them.","gameIdea":"Currency Explorer: compare example prices for the same item shown in different currencies.","challenge":"Find out what currency is used in a country you'd love to visit one day.","quiz":{"question":"What is a 'currency'?","options":["The specific kind of money a country uses","Any coin, anywhere","A type of bank","A kind of card"],"correct_answer":"The specific kind of money a country uses","explanation":"A currency is the particular named kind of money a country uses — like the pound, the dollar, or the euro — whether it's used as cash or moved digitally."},"feedbackMessage":{"success":"Exactly right — that's what currency means. 💷💵","retry":"Think about what Sam's parent explained needing for the trip."},"rewardMessage":"Coins earned for understanding what a currency actually is!","parentNote":"If your family has travelled internationally or has relatives in another country, this is a great week to show your child real examples of a different currency, and talk through why the same amount of money can look like very different numbers depending on the currency being used.","commonMisconception":"Children this age sometimes think 'currency' just means cash specifically, rather than the whole system (cash and digital) a country uses."}$jsonb$::jsonb, 20, 750, 1   ),
  ( 'strategist-currencies-l1', 'sky-exchange', 'currencies', 'strategist', 1, 'lesson', 'Understanding Exchange Rates', 'Understand what an exchange rate is and why it changes over time.', $jsonb${"shortIntroduction":"The same amount of money can be worth a different amount in another country — and that number keeps changing.","story":"Elena is comparing prices for something online, sold in a different currency than her own. She realises she can't just compare the numbers directly — she needs to know today's exchange rate to understand what she'd actually be paying in her own currency. She also notices that rate was different last month.","keyConcept":"An exchange rate is how much one currency is worth compared to another, and it changes over time based on many factors in the wider economy.","vocabulary":[{"term":"exchange rate","definition":"How much one currency is worth compared to another"},{"term":"conversion","definition":"Working out an amount in one currency using another currency's value"},{"term":"fluctuate","definition":"To change up and down over time"}],"explanation":"Exchange rates aren't fixed — they shift, sometimes daily, based on factors far beyond any individual's control. This means the same amount of foreign currency can be worth a bit more or a bit less in your own currency depending on exactly when you check. This is exactly why direct number comparisons between two different currencies can be misleading without checking the current rate.","interactiveActivity":"Convert the same price between two currencies using a given exchange rate, then see how the converted amount changes when the rate changes.","gameIdea":"Currency Explorer: compare real example prices for the same item across multiple currencies and exchange rates.","challenge":"Look up today's exchange rate between two real currencies you're curious about, and compare it to what it might have looked like a year ago.","quiz":{"question":"Why might the same amount of foreign currency be worth a different amount in your own currency next month?","options":["Because exchange rates change over time","Because currency wears out","Because banks change the numbers randomly","Because it never actually changes"],"correct_answer":"Because exchange rates change over time","explanation":"Exchange rates genuinely shift over time due to many economic factors — this is exactly why the same foreign amount can convert to a different amount in your own currency depending on when you check."},"feedbackMessage":{"success":"Exactly — exchange rates are never fixed for long. 📊","retry":"Think about what Elena noticed had changed between last month and today."},"rewardMessage":"Coins earned for understanding a genuinely real-world, tricky concept!","parentNote":"This lesson deliberately does not provide or endorse any specific exchange rate, since real rates change constantly and vary by provider (a bank, a currency exchange service, and a card provider can all quote slightly different rates for the same conversion). If your teen is planning real international spending, checking a current, reputable rate together is a great practical follow-up — this app doesn't attempt to be that live source.","commonMisconception":"Teenagers sometimes assume there's one single 'official' exchange rate at any moment, rather than understanding that rates can vary slightly by provider and change frequently.","countryVariesNote":"Exchange rates, and the fees different providers charge for currency conversion, vary by country, by provider, and change continuously — always check a current, reliable source for a real conversion rather than relying on a number from memory."}$jsonb$::jsonb, 25, 1000, 1   ),
  ( 'explorer-scams-l1', 'guardian-gate', 'scams', 'explorer', 1, 'lesson', 'Some Promises Are Too Good', 'Recognise that a promise of free money or prizes from a stranger is a warning sign, not a treat.', $jsonb${"shortIntroduction":"If a message says you've won something you never entered for, that's a big clue something's wrong.","story":"A pop-up on the screen says: 'YOU WON A FREE PRIZE! CLICK NOW!' You didn't enter any contest. A grown-up nearby says, 'That's not really a prize — that's a trick to get us to click something we shouldn't.'","keyConcept":"A message promising free money or prizes out of nowhere is usually a trick, not a real gift.","vocabulary":[{"term":"trick","definition":"Something that seems true but isn't, meant to fool you"},{"term":"stranger","definition":"Someone you don't know"}],"explanation":"Real prizes almost never show up out of nowhere from someone you don't know. If something online promises free money or a prize you never asked for, the safest thing to do is tell a grown-up and not click anything.","interactiveActivity":"Look at a few pretend pop-up messages and decide which ones are safe and which are tricks.","gameIdea":"Scam Detective: spot the suspicious message among a few normal ones.","challenge":"Tell a grown-up about any message you see that promises something for free and asks you to click quickly.","quiz":{"question":"A message says you won a prize you never entered for. What should you do?","options":["Tell a grown-up and don't click","Click it right away","Reply with your name","Keep it a secret"],"correct_answer":"Tell a grown-up and don't click","explanation":"Telling a grown-up and not clicking is the safest choice — real prizes don't usually show up from strangers out of nowhere."},"feedbackMessage":{"success":"Great instinct — that's exactly the safe thing to do! 🛡️","retry":"Think about what the grown-up in the story said about the pop-up."},"rewardMessage":"Coins earned for spotting a trick and staying safe!","parentNote":"At this age, the goal is simply building the reflex 'tell a grown-up, don't click' — not explaining phishing or scam mechanics in detail, which isn't necessary yet. If your child mentions a pop-up or message like this at home, treating it as a genuine 'well spotted!' moment (rather than a telling-off for having seen it at all) reinforces exactly the reporting behaviour you want.","commonMisconception":"Children this age sometimes believe a message must be true simply because it's on a screen and looks official."}$jsonb$::jsonb, 15, 500, 1   ),
  ( 'builder-scams-l1', 'guardian-gate', 'scams', 'builder', 1, 'lesson', 'Spotting a Scam', 'Identify common warning signs of an online scam, such as urgency, secrecy, and requests for personal information.', $jsonb${"shortIntroduction":"Scams usually share a few warning signs — once you know what to look for, they get much easier to spot.","story":"Zara gets a message claiming to be from a well-known game she plays: 'Your account will be deleted in 10 minutes unless you enter your password here!' It feels urgent and scary. Zara pauses instead of panicking, and notices three things: it's rushing her, it wants a password, and it arrived from an address that doesn't quite match the real game's usual messages.","keyConcept":"Scams often share warning signs: urgency (rushing you to act fast), secrecy (asking you to keep it quiet), and requests for personal information like passwords.","vocabulary":[{"term":"scam","definition":"A trick designed to get money or personal information dishonestly"},{"term":"urgency","definition":"Pressure to act quickly, without time to think"},{"term":"personal information","definition":"Private details like your name, address, or passwords"}],"explanation":"Real companies almost never ask for your password by message, and they rarely threaten instant consequences to pressure you into acting fast. Slowing down, and checking with a trusted adult before responding, is usually enough to see through the pressure.","interactiveActivity":"Read a few example messages and highlight the specific warning signs in each one.","gameIdea":"Scam Detective: identify the suspicious message among realistic-looking options.","challenge":"If you ever get a message that feels rushed or asks for a password, wait and check with a trusted adult before doing anything.","quiz":{"question":"Which of these is a common warning sign of a scam?","options":["Being rushed to act immediately","Taking your time to think","A message from someone you know well","A normal, everyday email"],"correct_answer":"Being rushed to act immediately","explanation":"Creating urgency — pushing you to act before you have time to think it through — is one of the most common scam techniques, because it stops people from pausing to notice the other warning signs."},"feedbackMessage":{"success":"Exactly — urgency is one of the biggest red flags. 🚩","retry":"Think about what Zara noticed that made her pause instead of reacting right away."},"rewardMessage":"Coins earned for learning to spot scam warning signs!","parentNote":"This lesson deliberately teaches general PATTERNS (urgency, secrecy, requests for personal information) rather than specific current scams, since scam tactics evolve constantly and any specific example would go stale. A great follow-up is agreeing on a simple family rule together: 'if a message asks for a password or feels urgent, always check with a grown-up first' — a rule is easier to remember under pressure than a list of examples.","commonMisconception":"Children this age sometimes believe scams are always obviously badly written or 'silly looking' — many real scams are polished and convincing."}$jsonb$::jsonb, 20, 750, 1   ),
  ( 'strategist-scams-l1', 'guardian-gate', 'scams', 'strategist', 1, 'lesson', 'Scams Target Emotions, Not Logic', 'Analyse how scams are designed to exploit specific emotions, and develop a habit of pausing before responding to financial pressure.', $jsonb${"shortIntroduction":"The best scams don't try to out-argue you — they try to make you feel something strong enough to skip thinking altogether.","story":"Marcus sees a message offering a 'guaranteed' way to multiply money quickly, from someone posing as a friend of a friend. It plays on excitement and greed. Later, Marcus sees a different message threatening a fake 'unpaid fine' unless he pays immediately — this one plays on fear instead. Different emotions, same underlying trick: skip the thinking, trigger the feeling, get the money.","keyConcept":"Scams are engineered to trigger a strong emotion — excitement, fear, urgency, or trust — specifically because a strong emotion makes people skip careful thinking.","vocabulary":[{"term":"emotional manipulation","definition":"Using someone's feelings to influence their decisions unfairly"},{"term":"too good to be true","definition":"An offer that seems unrealistically good, which is often a sign it's fake"},{"term":"verification","definition":"Checking that something is genuinely true before acting on it"}],"explanation":"Whether a scam uses excitement ('guaranteed returns'), fear ('you owe money now'), or trust ('a friend recommended this'), the mechanism is the same: trigger a strong feeling fast enough that the target acts before thinking it through. The single most reliable defence is a habit, not a specific piece of knowledge: pause, and verify independently, before sending money or personal information to anyone — no matter how the request is framed.","interactiveActivity":"Analyse a few realistic scam scenarios and identify which specific emotion each one is designed to trigger.","gameIdea":"Scam Detective: work through more advanced, realistic scam scenarios that mix multiple techniques.","challenge":"Think of a time you felt a strong urge to act quickly about money (even a small purchase) — what emotion was driving it, and was the urgency actually real?","quiz":{"question":"What is the common mechanism behind most financial scams, regardless of which emotion they use?","options":["Triggering a strong feeling to bypass careful thinking","Always using fear specifically","Only targeting older people","Requiring advanced technical skill to fall for"],"correct_answer":"Triggering a strong feeling to bypass careful thinking","explanation":"Different scams use different emotions — excitement, fear, trust — but the underlying mechanism is the same: a strong feeling is used to short-circuit careful thinking before someone can verify the claim independently."},"feedbackMessage":{"success":"Exactly right — once you see the mechanism, the specific disguise matters less. 🎯","retry":"Think about what Marcus's two different scam examples actually had in common underneath the different emotions."},"rewardMessage":"Coins earned for understanding how scams really work underneath the surface.","parentNote":"This lesson is intentionally about pattern recognition and a pause-and-verify habit, not about listing current scams, since scam tactics change constantly and this content would otherwise go stale quickly. If your teen is managing any of their own money independently (even a small amount), talking through your own family's 'always double-check with someone before sending money anywhere new' rule is a genuinely valuable, concrete follow-up.","commonMisconception":"Teenagers sometimes believe they're too tech-savvy to fall for a scam — but well-designed scams are engineered around emotional response, not technical sophistication, so confidence in tech skills doesn't provide the protection it seems to."}$jsonb$::jsonb, 25, 1000, 1   ),
  ( 'explorer-long_term_thinking-l1', 'horizon-peaks', 'long_term_thinking', 'explorer', 1, 'lesson', 'Waiting Can Pay Off', 'Understand that waiting a little can sometimes lead to something better.', $jsonb${"shortIntroduction":"Sometimes the best things come to the people who can wait just a little bit.","story":"You're offered one small sticker right now, or three stickers if you wait until tomorrow. It's hard to wait! But you decide to be patient — and the next day, you have three stickers instead of just one.","keyConcept":"Waiting a little bit can sometimes get you more than rushing to have something right away.","vocabulary":[{"term":"wait","definition":"To not do something right away"},{"term":"patient","definition":"Able to wait calmly without rushing"}],"explanation":"It's not always easy to wait, especially when you really want something now! But sometimes, being patient means ending up with more, or something better, than if you'd rushed.","interactiveActivity":"Choose between a smaller reward now or a bigger reward after waiting, in a few playful scenarios.","gameIdea":"Reach Your Goal: build up a fictional coin pile over several days toward a bigger prize.","challenge":"Try waiting for something small this week instead of getting it right away, and notice how it feels.","quiz":{"question":"In the story, what happened when you waited until tomorrow?","options":["You got three stickers instead of one","You got nothing","The sticker disappeared","Nothing changed"],"correct_answer":"You got three stickers instead of one","explanation":"Waiting turned one sticker into three — a small example of how patience can sometimes lead to more."},"feedbackMessage":{"success":"You remembered! Waiting paid off. ⏳","retry":"Think back to what happened the next day in the story."},"rewardMessage":"Coins earned for thinking about waiting and patience!","parentNote":"This lesson introduces the idea behind delayed gratification in the gentlest possible way — a real, lived example (letting your child choose between a smaller treat now and a bigger one after waiting a day or two) reinforces this far better than a conversation alone. There's no need to frame 'not waiting' as a failure — plenty of adults find patience hard too.","commonMisconception":"At this age, 'later' can feel abstract and almost unreal compared to something available right now, making waiting feel much harder than it will later in life."}$jsonb$::jsonb, 15, 500, 1   ),
  ( 'builder-long_term_thinking-l1', 'horizon-peaks', 'long_term_thinking', 'builder', 1, 'lesson', 'Planning a Few Steps Ahead', 'Practise thinking a few steps ahead when making a money decision.', $jsonb${"shortIntroduction":"A good money decision often means picturing what happens next — not just what happens right now.","story":"Finn has enough saved for either a small toy today or, if he waits three more weeks, a much bigger set he's been wanting. He pictures both futures: buying small now and feeling done, or waiting and getting the bigger set he actually wanted more. Picturing it ahead of time makes the choice much clearer.","keyConcept":"Thinking ahead about the likely outcome of a choice — not just the immediate feeling — leads to better decisions.","vocabulary":[{"term":"plan ahead","definition":"Thinking about what will happen before you decide"},{"term":"outcome","definition":"What ends up happening as a result of a choice"}],"explanation":"Before a money decision, it helps to picture the outcome a few weeks ahead, not just how you feel right now. Finn didn't just ask 'what do I want right now?' — he asked 'which choice will I be happier with in a few weeks?'","interactiveActivity":"Work through a few money decisions and predict the likely outcome a few weeks ahead for each option.","gameIdea":"Reach Your Goal: plan coin allocation across several weeks toward a target.","challenge":"Before your next purchase decision, try picturing how you'll feel about it a few weeks later.","quiz":{"question":"What helped Finn make his decision more clearly?","options":["Picturing the outcome a few weeks ahead","Deciding as fast as possible","Asking a stranger","Ignoring the choice completely"],"correct_answer":"Picturing the outcome a few weeks ahead","explanation":"Finn's decision got clearer once he pictured how each choice would feel a few weeks later, not just in the moment — that's the core skill this lesson is building."},"feedbackMessage":{"success":"Right — thinking ahead really does change decisions. 🧭","retry":"Think about what Finn actually did differently before deciding."},"rewardMessage":"Coins earned for practising thinking a few steps ahead!","parentNote":"A genuinely useful family habit at this age is simply asking, before a purchase: 'how do you think you'll feel about this in a month?' It's a light, curious question rather than a test, and it builds a genuinely transferable reasoning skill — not just about money, but decision-making generally.","commonMisconception":"At this age, children can find it hard to vividly imagine a future feeling, which makes the present moment's want feel disproportionately more real and urgent."}$jsonb$::jsonb, 20, 750, 1   ),
  ( 'strategist-long_term_thinking-l1', 'horizon-peaks', 'long_term_thinking', 'strategist', 1, 'lesson', 'Big Decisions, Long Timelines', 'Practise weighing a decision''s short-term appeal against its long-term consequences using a real, relatable scenario.', $jsonb${"shortIntroduction":"The biggest money decisions in life play out over years, not days — and that's genuinely hard to plan for.","story":"Aisha is thinking about how she'll spend money she earns from a part-time job — all of it on things she wants now, or some of it set aside for something bigger years from now, like a car, further education, or simply more freedom to make future choices. There's no single right answer. But she notices that not deciding on purpose is itself a decision — it just means spending everything by default.","keyConcept":"Long-term financial decisions involve genuine trade-offs with no single right answer, but making the choice deliberately — rather than by default — tends to lead to outcomes people are more satisfied with later.","vocabulary":[{"term":"long-term consequence","definition":"An effect of a decision that shows up much later, not right away"},{"term":"deliberate decision","definition":"A choice made on purpose, having thought it through"},{"term":"by default","definition":"What happens automatically when no active choice is made"}],"explanation":"Big financial decisions — how much to spend versus save over months or years, whether to prioritise something now versus a future goal — rarely have one objectively correct answer. What tends to separate a good long-term decision from a bad one isn't the specific choice, but whether it was made on purpose, having actually weighed the trade-off, rather than happening by default because nobody paused to decide.","interactiveActivity":"Work through a realistic multi-month scenario, weighing a 'spend now' option against a 'save for later' option, and articulate the reasoning either way.","gameIdea":"The Money Life Simulator: make a series of connected weekly decisions and see how they add up over a longer, simulated timeline.","challenge":"Think of one real long-term decision (even a small one) in your own life right now, and write down the trade-off in one sentence.","quiz":{"question":"According to this lesson, what tends to separate a good long-term financial decision from a bad one?","options":["Whether it was made deliberately, having weighed the trade-off","Always choosing to save everything","Always choosing to spend everything","Never making any decision at all"],"correct_answer":"Whether it was made deliberately, having weighed the trade-off","explanation":"There's rarely one universally correct answer for a long-term trade-off — but a decision made on purpose, having genuinely weighed the options, tends to hold up better than one that happened by default."},"feedbackMessage":{"success":"Exactly — the deliberateness matters more than any single 'correct' choice. 🎯","retry":"Think about what Aisha realised about not deciding at all."},"rewardMessage":"Coins earned for thinking seriously about a genuinely hard, real kind of decision.","parentNote":"This lesson deliberately avoids telling teenagers what the 'right' long-term financial choice is, since that depends entirely on individual circumstances, goals, and values this app has no basis to judge. It is not financial advice, and isn't meant to be — it's meant to build the habit of making financial decisions on purpose rather than by default. If your teen wants to talk through a real decision they're facing, that conversation is best had directly with you, using your family's actual circumstances.","commonMisconception":"Teenagers sometimes look for a single 'correct' formula for balancing spending and saving, rather than recognising it as a genuine, ongoing personal trade-off with no universal answer."}$jsonb$::jsonb, 25, 1000, 1   ),
  ( 'explorer-giving-l1', 'kindness-grove', 'giving', 'explorer', 1, 'lesson', 'The Joy of Sharing', 'Understand that giving some of what you have to help others is a kind and valuable choice.', $jsonb${"shortIntroduction":"Sharing a little of what you have can feel just as good as getting something new.","story":"You have five coins. Your friend has none, and really wants to join the game that costs one coin to play. You give your friend a coin. Now you both get to play — and somehow, sharing that one coin feels really good.","keyConcept":"Giving away some of what you have to help someone else is a kind, valuable choice, not a loss.","vocabulary":[{"term":"give","definition":"To let someone else have something of yours"},{"term":"share","definition":"To let others use or have part of what you have"}],"explanation":"You don't need a lot of coins to be able to give — even a small amount can make a real difference to someone else, and it can feel really good to help.","interactiveActivity":"Decide how many of your fictional coins to share with a friend character in a short scenario.","gameIdea":"Money Choices: pick between spending on yourself or sharing, in a few gentle, low-pressure scenarios.","challenge":"Think of one small thing you could share with someone this week — a toy, a snack, or your time.","quiz":{"question":"In the story, what happened when you shared a coin with your friend?","options":["You both got to play the game","You lost everything","Your friend got upset","Nothing changed"],"correct_answer":"You both got to play the game","explanation":"Sharing one coin meant your friend could join in too — a small gift that made a real difference for both of you."},"feedbackMessage":{"success":"That's the spirit of giving! 💛","retry":"Think about what happened after you shared your coin in the story."},"rewardMessage":"Coins earned for thinking kindly about sharing!","parentNote":"Giving is included as its own topic because generosity is a genuine, valuable financial habit worth building early, alongside saving and spending — not an afterthought. At this age, giving is best kept concrete and small-scale (sharing a toy, a snack, or a small amount) rather than abstract charitable concepts, which are easier to introduce meaningfully a bit later.","commonMisconception":"Children this age sometimes worry that giving something away means they'll have nothing left, rather than seeing it as sharing from a place of having enough."}$jsonb$::jsonb, 15, 500, 1   ),
  ( 'builder-giving-l1', 'kindness-grove', 'giving', 'builder', 1, 'lesson', 'Giving on Purpose', 'Practise setting aside a small, deliberate portion of money for giving, as part of a simple money plan.', $jsonb${"shortIntroduction":"Giving doesn't have to be an afterthought — you can plan for it, just like saving or spending.","story":"Omar decides to split his allowance three ways every week: some to spend, some to save, and a small amount set aside just for giving — maybe to a friend in need, a class fundraiser, or a cause he cares about. Deciding on the split ahead of time means giving never feels like an awkward, last-minute decision.","keyConcept":"Giving can be planned for deliberately, as one part of how you handle money, not just an occasional impulse.","vocabulary":[{"term":"set aside","definition":"To deliberately keep some money for a specific purpose"},{"term":"cause","definition":"A goal or issue someone chooses to support"}],"explanation":"Just like a savings goal, a 'giving' amount can be planned for ahead of time — even a small, regular portion. Deciding this in advance, rather than only when someone specifically asks, tends to make giving feel like a steady habit rather than pressure.","interactiveActivity":"Split a fixed amount of fictional coins across spend, save, and give categories.","gameIdea":"Build a Budget: allocate coins across categories, including a giving category.","challenge":"Talk with a grown-up about a cause or person your family has helped, or might like to help.","quiz":{"question":"What did Omar do that made giving feel less like a last-minute decision?","options":["He planned a giving amount ahead of time","He only gave when asked","He never gave anything","He gave away everything at once"],"correct_answer":"He planned a giving amount ahead of time","explanation":"By deciding on a giving amount in advance, as part of his regular plan, Omar didn't have to make an awkward decision each time — it was already part of the plan."},"feedbackMessage":{"success":"Exactly — planning ahead makes giving feel natural. 🌱","retry":"Think about what Omar decided to do with his allowance every week."},"rewardMessage":"Coins earned for thinking about giving as part of a real plan!","parentNote":"If your family already gives to causes or helps others in some way, involving your child in even a small, real decision about it (which cause, how much, why) makes this concept concrete rather than abstract. There's no 'correct' amount to give — the goal of this lesson is the habit of planning for it, not a specific percentage.","commonMisconception":"Children this age sometimes assume giving only counts if it's a large or dramatic amount, rather than recognising that small, regular giving is meaningful too."}$jsonb$::jsonb, 20, 750, 1   ),
  ( 'strategist-giving-l1', 'kindness-grove', 'giving', 'strategist', 1, 'lesson', 'Giving Thoughtfully', 'Consider how to think critically about where and how to give, alongside the value of giving itself.', $jsonb${"shortIntroduction":"Wanting to help is easy. Thinking clearly about HOW to help well takes a bit more care.","story":"Sofia wants to support a cause she cares about, but she's seen news stories about donations not always reaching the people they're meant to help. Instead of giving up on the idea, she does a little research first — looking at what a cause or organisation actually does with what it receives, before deciding where to give her time or money.","keyConcept":"Giving is valuable, and thinking carefully about where and how to give — not just that you're giving — helps make sure your generosity actually has the impact you intend.","vocabulary":[{"term":"impact","definition":"The real effect or difference something makes"},{"term":"research","definition":"Looking into something carefully before deciding"},{"term":"transparency","definition":"Being open and clear about how something works"}],"explanation":"Not all ways of giving are equally effective, and that's worth thinking about rather than ignoring — it doesn't make giving less valuable, it makes it more thoughtful. A little research (what does this cause actually do, how clear are they about it) helps make sure your generosity reaches its intended purpose.","interactiveActivity":"Compare a few example causes or ways of giving and discuss what information would help decide between them.","gameIdea":"Money Choices: weigh a giving decision that includes some genuine, realistic trade-offs.","challenge":"Pick a cause you care about and find out one concrete thing about how it actually uses support it receives.","quiz":{"question":"According to this lesson, why might someone research a cause before giving to it?","options":["To help make sure the giving has the intended impact","Because giving is never worth doing","Because all causes are the same","Because research replaces the need to give at all"],"correct_answer":"To help make sure the giving has the intended impact","explanation":"Researching a cause doesn't make giving less meaningful — it helps make sure the generosity actually reaches and helps the people or purpose it's meant to."},"feedbackMessage":{"success":"Exactly — thoughtful giving and generous giving aren't opposites. 💛","retry":"Think about why Sofia chose to look into the cause rather than either giving blindly or not giving at all."},"rewardMessage":"Coins earned for thinking seriously about giving well, not just giving.","parentNote":"This lesson deliberately doesn't recommend any specific charity or cause, since that's a personal and family decision this app has no basis to make for you. If your teen wants to explore real charitable giving, looking at a cause's own published information together is a genuinely good, practical activity that goes beyond what this lesson alone can offer.","commonMisconception":"Teenagers sometimes swing to either extreme — giving without any thought at all, or becoming so skeptical of all giving that they stop considering it altogether — rather than landing on thoughtful, informed generosity."}$jsonb$::jsonb, 25, 1000, 1   );
